import{_ as o,o as a,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Lei de Proteção ao Consumidor","description":"","frontmatter":{},"headers":[],"relativePath":"pt/42-消费者保护法.md","filePath":"pt/42-消费者保护法.md","lastUpdated":1789183869000}'),s={name:"pt/42-消费者保护法.md"};function d(t,e,n,c,m,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="lei-de-protecao-ao-consumidor" tabindex="-1">Lei de Proteção ao Consumidor <a class="header-anchor" href="#lei-de-protecao-ao-consumidor" aria-label="Permalink to &quot;Lei de Proteção ao Consumidor&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>42</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Direitos do Consumidor, Transação Justa, Anti-fraude, Responsabilidade do Produto, Mercado Simbiótico</td></tr></tbody></table><h2 id="i-objetivo-legislativo-e-ambito-de-aplicacao" tabindex="-1">I. Objetivo Legislativo e Âmbito de Aplicação <a class="header-anchor" href="#i-objetivo-legislativo-e-ambito-de-aplicacao" aria-label="Permalink to &quot;I. Objetivo Legislativo e Âmbito de Aplicação&quot;">​</a></h2><p>A 《Lei de Proteção ao Consumidor》 é uma das leis centrais do sistema jurídico da civilização simbiótica de âncoras, e junto com a 《Lei Trabalhista Simbiótica》 constitui os dois pilares da vida econômica. Esta lei visa proteger os direitos e interesses legítimos de todos os consumidores dentro de Hengyuanzhou, regulamentar as atividades de transação de mercado, manter a ordem de mercado justa, íntegra e simbiótica, e prevenir a violação dos direitos e interesses de todos os seres por atividades comerciais predatórias.</p><p>Esta lei aplica-se a todos os consumidores dentro de Hengyuanzhou que compram, usam mercadorias ou recebem serviços para atender às necessidades de vida pessoal ou familiar, bem como aos operadores que fornecem mercadorias ou serviços aos consumidores. Transações interdimensionais também estão sujeitas a esta lei, mas regras detalhadas de implementação podem ser formuladas de acordo com as diferenças entre planos.</p><h2 id="ii-direitos-fundamentais-do-consumidor" tabindex="-1">II. Direitos Fundamentais do Consumidor <a class="header-anchor" href="#ii-direitos-fundamentais-do-consumidor" aria-label="Permalink to &quot;II. Direitos Fundamentais do Consumidor&quot;">​</a></h2><p>Esta lei estabelece que os consumidores desfrutam dos seguintes nove direitos fundamentais:</p><table tabindex="0"><thead><tr><th>Direito</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Direito à Segurança</td><td>O consumidor, ao comprar, usar mercadorias e receber serviços, desfruta do direito de que sua segurança pessoal e patrimonial não seja prejudicada</td></tr><tr><td>Direito à Informação Verdadeira</td><td>O consumidor tem o direito de conhecer a situação real das mercadorias que compra ou usa ou dos serviços que recebe, incluindo ingredientes, eficácia, riscos, etc.</td></tr><tr><td>Direito à Escolha Autônoma</td><td>O consumidor tem o direito de escolher autonomamente mercadorias ou serviços, tem o direito de comparar, identificar e selecionar, e recusar transações forçadas</td></tr><tr><td>Direito à Transação Justa</td><td>O consumidor tem o direito de obter condições de transação justas, como garantia de qualidade, preço razoável, medição correta, etc.</td></tr><tr><td>Direito à Indenização por Lei</td><td>O consumidor que sofrer danos pessoais ou patrimoniais devido à compra, uso de mercadorias ou recebimento de serviços desfruta do direito de obter indenização de acordo com a lei</td></tr><tr><td>Direito de Associação para Defesa de Direitos</td><td>O consumidor tem o direito de formar ou ingressar em organizações de consumidores de acordo com a lei, para defender seus próprios direitos e interesses legítimos</td></tr><tr><td>Direito à Obtenção de Conhecimento</td><td>O consumidor tem o direito de obter conhecimento e informações relacionados ao consumo e à proteção dos direitos e interesses do consumidor</td></tr><tr><td>Direito ao Respeito</td><td>O consumidor, ao comprar, usar mercadorias e receber serviços, desfruta do direito de que sua dignidade pessoal e costumes étnicos sejam respeitados</td></tr><tr><td>Direito de Supervisão</td><td>O consumidor tem o direito de supervisionar mercadorias e serviços, bem como o trabalho de proteção dos direitos e interesses do consumidor, e fazer críticas e sugestões</td></tr></tbody></table><h2 id="iii-obrigacoes-dos-operadores" tabindex="-1">III. Obrigações dos Operadores <a class="header-anchor" href="#iii-obrigacoes-dos-operadores" aria-label="Permalink to &quot;III. Obrigações dos Operadores&quot;">​</a></h2><p>Ao fornecer mercadorias ou serviços aos consumidores, os operadores devem cumprir as seguintes obrigações:</p><ol><li><strong>Obrigação de Operar de Acordo com a Lei</strong>: O operador deve obedecer à Constituição e às leis, e realizar atividades comerciais dentro do escopo comercial aprovado.</li><li><strong>Obrigação de Garantia de Segurança</strong>: O operador deve garantir que as mercadorias ou serviços por ele fornecidos atendam aos requisitos de garantia de segurança pessoal e patrimonial, e deve fazer explicações verdadeiras e avisos claros sobre mercadorias e serviços que possam colocar a segurança em risco.</li><li><strong>Obrigação de Informação Verdadeira</strong>: O operador deve fornecer aos consumidores informações verdadeiras sobre mercadorias ou serviços, e não pode fazer propaganda falsa ou enganosa. Mercadorias e serviços de categoria de cultivo devem marcar verdadeiramente os limites de eficácia e riscos potenciais.</li><li><strong>Obrigação de Garantia de Qualidade</strong>: O operador deve garantir que, em condições normais de uso de mercadorias ou recebimento de serviços, as mercadorias ou serviços por ele fornecidos tenham a qualidade, desempenho, finalidade e prazo de validade que deveriam ter.</li><li><strong>Obrigação de Transação Justa</strong>: O operador não pode, por meio de cláusulas padrão, avisos, declarações, cartazes de loja, etc., fazer disposições injustas e irracionais para os consumidores, como excluir ou limitar os direitos do consumidor, reduzir ou isentar a responsabilidade do operador, aumentar a responsabilidade do consumidor, etc.</li><li><strong>Obrigação de Serviço Pós-Venda</strong>: O operador deve, de acordo com as disposições do Estado ou com o acordo com o consumidor, assumir a responsabilidade por reparo, troca, devolução e outros serviços pós-venda.</li><li><strong>Obrigação de Proteção à Privacidade</strong>: O operador deve proteger as informações pessoais e dados de consciência do consumidor, e não pode coletar, usar ou vazar sem o consentimento do consumidor.</li></ol><h2 id="iv-resolucao-de-disputas-e-responsabilidade-juridica" tabindex="-1">IV. Resolução de Disputas e Responsabilidade Jurídica <a class="header-anchor" href="#iv-resolucao-de-disputas-e-responsabilidade-juridica" aria-label="Permalink to &quot;IV. Resolução de Disputas e Responsabilidade Jurídica&quot;">​</a></h2><p>Quando surgirem disputas de direitos e interesses do consumidor entre consumidores e operadores, elas podem ser resolvidas pelos seguintes meios:</p><ul><li>Negociação e conciliação com o operador</li><li>Solicitar mediação a organizações de consumidores</li><li>Reclamar aos departamentos administrativos competentes</li><li>Solicitar arbitragem a uma instituição de arbitragem de acordo com o acordo de arbitragem celebrado com o operador</li><li>Intentar ação no Tribunal Simbiótico</li></ul><p>O operador que violar as disposições desta lei e infringir os direitos e interesses legítimos do consumidor deve assumir as seguintes responsabilidades:</p><table tabindex="0"><thead><tr><th>Atividade Ilegal</th><th>Responsabilidade Jurídica</th></tr></thead><tbody><tr><td>Fornecer mercadorias ou serviços defeituosos causando danos</td><td>Assumir responsabilidade por indenização, incluindo despesas médicas, indenização por perda de trabalho, indenização por invalidez, etc.</td></tr><tr><td>Atividade fraudulenta</td><td>Aumentar a indenização de acordo com a solicitação do consumidor, o valor é três vezes o preço das mercadorias compradas pelo consumidor ou a taxa dos serviços recebidos</td></tr><tr><td>Propaganda falsa</td><td>Ordenar a cessação da atividade ilegal, eliminar a influência, impor multa</td></tr><tr><td>Transação forçada</td><td>Ordenar a correção, reembolsar taxas irracionais, impor multa</td></tr><tr><td>Infringir a privacidade do consumidor</td><td>Assumir indenização por danos morais, em casos graves, responsabilidade criminal</td></tr></tbody></table><h2 id="v-organizacoes-de-consumidores-e-supervisao-social" tabindex="-1">V. Organizações de Consumidores e Supervisão Social <a class="header-anchor" href="#v-organizacoes-de-consumidores-e-supervisao-social" aria-label="Permalink to &quot;V. Organizações de Consumidores e Supervisão Social&quot;">​</a></h2><p>O Estado incentiva e apoia todas as organizações e indivíduos a realizar supervisão social sobre atividades que prejudicam os direitos e interesses legítimos do consumidor. A Associação de Consumidores é uma organização social estabelecida de acordo com a lei para realizar supervisão social sobre mercadorias e serviços e proteger os direitos e interesses legítimos do consumidor, desempenhando as seguintes funções:</p><ol><li>Fornecer informações de consumo e serviços de consultoria aos consumidores</li><li>Participar da supervisão e inspeção de mercadorias e serviços por departamentos administrativos competentes</li><li>Refletir, consultar e fazer sugestões aos departamentos administrativos competentes sobre questões relacionadas aos direitos e interesses legítimos do consumidor</li><li>Receber reclamações de consumidores e investigar e mediar os assuntos reclamados</li><li>Apoiar os consumidores lesados a intentar ações contra atividades que prejudicam os direitos e interesses legítimos do consumidor</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Lei de Proteção ao Consumidor》 é a guardiã da ordem de mercado da civilização simbiótica de âncoras. Ao conceder aos consumidores direitos plenos, restringir o comportamento dos operadores e estabelecer um mecanismo diversificado de resolução de disputas, ela garante que as transações de mercado operem em uma trilha justa, íntegra e simbiótica, prevenindo que o setor comercial se torne um novo terreno fértil para atividades predatórias.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>41-共生劳动法 (Lei Trabalhista Simbiótica)</li><li>47-反垄断法 (Lei Antimonopólio)</li><li>36-社会结构与阶层流动 (Estrutura Social e Mobilidade de Classes)</li></ul>',23)])])}const b=o(s,[["render",d]]);export{p as __pageData,b as default};
